<?php
use App\Core\Security;
$baseUrl=rtrim((require BASE_PATH.'/config/app.php')['url'],'/'); $reviews=$reviews??[]; $message=$message??null;
?>
<section class="dashboard-page" data-reveal><header class="dashboard-heading"><div><button class="dashboard-menu-toggle" type="button" data-dashboard-toggle aria-expanded="false" aria-controls="dashboard-sidebar" aria-label="Open dashboard menu"><span></span><span></span><span></span></button><p class="eyebrow">ADMIN WORKSPACE</p><h1>Review moderation</h1><p>Approve reviews to publish them on the homepage, or reject them.</p></div></header>
<?php if($message): ?><p class="form-message" role="status"><?= Security::escape($message) ?></p><?php endif; ?>
<?php if($reviews===[]): ?><section class="dashboard-panel"><div class="dashboard-empty"><div><h2>No reviews awaiting approval</h2><p>New submitted reviews will appear here.</p></div></div></section><?php else: ?>
<div class="dashboard-course-list"><?php foreach($reviews as $review): ?><article class="dashboard-panel"><div class="dashboard-panel-heading"><div><p class="eyebrow"><?= Security::escape(ucfirst($review['reviewer_type'])) ?> · <?= (int)$review['rating'] ?>/5 stars</p><h2><?= Security::escape($review['full_name']) ?></h2></div><time><?= Security::escape($review['created_at']) ?></time></div><p><?= Security::escape($review['context_label']??'') ?></p><blockquote><?= nl2br(Security::escape($review['content'])) ?></blockquote><div class="dashboard-actions"><?php foreach(['approved'=>'Approve and publish','rejected'=>'Reject'] as $decision=>$label): ?><form method="post" action="<?= Security::escape($baseUrl) ?>/admin/reviews/decision"><input type="hidden" name="_csrf" value="<?= Security::escape(Security::csrfToken()) ?>"><input type="hidden" name="review_id" value="<?= (int)$review['id'] ?>"><input type="hidden" name="decision" value="<?= Security::escape($decision) ?>"><button class="button <?= $decision==='rejected'?'button-secondary':'' ?>" type="submit"><?= Security::escape($label) ?></button></form><?php endforeach; ?></div></article><?php endforeach; ?></div><?php endif; ?></section>
